  ('c034cce6-9920-4910-b426-32181d3abaf8', $$Natuurkunde$$, $$HAVO$$, $$Kaval$$, $$HAVO Natuurkunde 2025-I$$),
  ('a4044903-7b76-477a-9a11-028ed6a87a61', $$Natuurkunde$$, $$HAVO$$, $$Papieren schakelingen$$, $$HAVO Natuurkunde 2025-I$$),
