  ('3875cae1-4304-4a8b-bc22-89251d76fc20', 'a4044903-7b76-477a-9a11-028ed6a87a61', 7,
   $$[{"domain": "Meten en regelen", "subdomain": "Gebruik van elektriciteit"}]$$::jsonb,
